<?php
$disabled = !empty($read_only) ? 'disabled' : '';
$action = !empty($form['id']) ? admin_url('/users/edit/' . (int) $form['id']) : admin_url('/users/new');
$overrides = (array) ($form['overrides'] ?? array());
$grouped = array();
foreach ((array) $permissions as $permission) { $grouped[$permission['module']][] = $permission; }
?>
<header class="admin-page-head compact-head"><div><a class="admin-back-link" href="<?= e(admin_url('/users')) ?>">&lt;- Back to users</a><p class="admin-eyebrow">Team / access</p><h1><?= !empty($form['id']) ? 'Edit team member' : 'Add team member' ?></h1><p class="admin-lede">Keep access intentional, visible and easy to review.</p></div></header>
<?php if (!empty($errors)): ?><div class="admin-alert error" id="user-form-errors" role="alert"><ul><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="admin-editor-form" method="post" action="<?= e($action) ?>"<?= !empty($errors) ? ' aria-describedby="user-form-errors"' : '' ?>><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($form['id'] ?? 0) ?>"><div class="editor-layout"><main class="editor-main"><section class="admin-panel editor-panel"><div class="form-grid"><label><span>Name <b>*</b></span><input name="name" value="<?= e($form['name'] ?? '') ?>" required <?= $disabled ?>></label><label><span>Email <b>*</b></span><input type="email" name="email" value="<?= e($form['email'] ?? '') ?>" required <?= $disabled ?>></label><label><span>Job title</span><input name="title" value="<?= e($form['title'] ?? '') ?>" <?= $disabled ?>></label><label><span>Role <b>*</b></span><select id="user-role" name="role_id" aria-describedby="user-role-help" required <?= $disabled ?>><option value="">Choose a role</option><?php foreach ((array) $roles as $role): ?><option value="<?= (int) $role['id'] ?>" <?= (int) ($form['role_id'] ?? 0) === (int) $role['id'] ? 'selected' : '' ?> <?= empty($role['is_active']) ? 'disabled' : '' ?>><?= e($role['title']) ?></option><?php endforeach; ?></select><small id="user-role-help">Only active roles can be assigned. Owners control access to roles.</small></label><label><span><?= !empty($form['id']) ? 'New password' : 'Password' ?></span><input id="user-password" type="password" name="password" minlength="12" aria-describedby="user-password-help" autocomplete="new-password" <?= $disabled ?>><small id="user-password-help">At least 12 characters. Leave blank when editing to keep the current password.</small></label><label><span>Confirm password</span><input id="user-password-confirmation" type="password" name="password_confirmation" minlength="12" aria-describedby="user-password-help" autocomplete="new-password" <?= $disabled ?>></label><label class="toggle-field"><span>Active account</span><input type="checkbox" name="is_active" value="1" <?= !isset($form['is_active']) || !empty($form['is_active']) ? 'checked' : '' ?> <?= $disabled ?>><strong>Can sign in</strong></label></div></section><section class="admin-panel editor-panel"><div class="panel-heading"><div><p class="admin-eyebrow">Overrides</p><h2 id="user-overrides-heading">Per-user exceptions</h2></div></div><p id="user-overrides-help" class="form-note">Role inherited is the default. Choose Allow or Deny only when this person needs an explicit exception.</p><div class="permission-groups" role="group" aria-labelledby="user-overrides-heading" aria-describedby="user-overrides-help"><?php foreach ($grouped as $module => $items): ?><fieldset class="permission-group"><legend><?= e(ucwords(str_replace(array('_', '-'), ' ', $module))) ?></legend><?php foreach ($items as $permission): $code = (string) $permission['code']; $effect = $overrides[$code] ?? ''; ?><div class="override-item"><strong><?= e($permission['title']) ?></strong><small><?= e($code) ?></small><select name="overrides[<?= e($code) ?>]" aria-label="Override for <?= e($permission['title']) ?>" <?= $disabled ?>><option value="">Role inherited</option><option value="allow" <?= $effect === 'allow' ? 'selected' : '' ?>>Allow</option><option value="deny" <?= $effect === 'deny' ? 'selected' : '' ?>>Deny</option></select></div><?php endforeach; ?></fieldset><?php endforeach; ?></div></section></main></div><?php if (empty($read_only)): ?><div class="editor-submit"><a class="admin-cancel-link" href="<?= e(admin_url('/users')) ?>">Cancel</a><button class="admin-primary-button" type="submit">Save team member <span aria-hidden="true">-&gt;</span></button></div><?php endif; ?></form>
